pages['reviews.html']=("Reviews | Dallas Party Bike","What riders say about Dallas Party Bike.",ph("1,403 reviews. One verdict: fun.","Rated “Excellent” across 1,403 reviews · 5.0 on Tripadvisor (private rental, 244 reviews) · 4.9 (pub crawl, 292 reviews).")+'<section><div class="wrap"><div class="grid g3" id="rv"></div><p class="note" style="margin-top:20px">Quotes reproduced as written (some trimmed with …). Sources noted on each review.</p></div></section>','<script>rv.innerHTML=DPB.reviews.map(reviewCard).join("")</script>')
pages['faq.html']=("FAQ & Ride Rules | Dallas Party Bike","Everything you need to know before you ride.",ph("FAQ & ride rules","Everything you need to know before you ride — from what to bring to how the party works.")+'<section><div class="wrap"><h2>The rules of the ride</h2><div class="grid rules" id="ru" style="margin-bottom:50px"></div><h2>Frequently asked questions</h2><div id="fq"></div></div></section>',
'<script>ru.innerHTML=DPB.policies.map(p=>`<div class="rule"><div class="i">${p.icon}</div><div><b>${p.t}</b><p>${p.d}</p></div></div>`).join("");fq.innerHTML=DPB.faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")</script>')
pages['about.html']=("About | Dallas Party Bike","Dallas Party Bike — Deep Ellum's pedal-powered party.",ph("Fun on wheels with great people","Six party bikes, 15 seats each, and a crew of captains who bring the party to Deep Ellum.")+'''
<section><div class="wrap grid g2" style="align-items:center"><img src="assets/big-group.jpg" style="border-radius:var(--r)" alt=""><div><h2>Born in Deep Ellum</h2><p>We roll out of 3909 Elm St, right in the heart of Deep Ellum — famous for its live music, street art and nightlife. Our bikes are pedal-powered with an electric assist, fully loaded with a Bluetooth sound system and LED party lights.</p><p>Groups from 6 to 90 ride with us for birthdays, bachelorettes, bachelor parties, family reunions and corporate team building.</p>
<p class="note"><span class="ph-tag">PLACEHOLDER</span> Founding story, year started and owner bio — add from owner.</p></div></div></section>
<section class="dark"><div class="wrap"><div class="sec-head"><h2>Meet the captains</h2><p>Names our riders mention again and again in reviews.</p></div><div class="grid g3" id="cr"></div><p class="note" style="color:#aaa;margin-top:14px"><span class="ph-tag">PLACEHOLDER</span> Crew photos & bios — pull from FlashDash crew profiles.</p></div></section>''',
'<script>cr.innerHTML=DPB.crew.map(n=>`<div class="step" style="padding:18px"><h3 style="margin:0">${n}</h3></div>`).join("")</script>')
